    """Return (started_only, completed) test paths parsed from progress lines.

    ``started_only`` are tests announced via "[N/M] (P%): <path>" that never
    reported a "took" suffix; ``completed`` are those that did.
    """
    started_only = []
    completed = []
    for line in strip_ansi(stdout).splitlines():
        stripped = line.strip()
        took_match = TEST_RUNTIME_PATTERN.match(stripped)
        if took_match:
            completed.append(took_match.group(1))
            continue
        start_match = PROGRESS_START_PATTERN.match(stripped)
        if start_match:
            started_only.append(start_match.group(1))
    return started_only, completed


def _identify_timed_out_test(stdout: str, batch: list):
    started_only, completed = _parse_progress_lines(stdout)
    if started_only or completed:
        completed_set = set(completed)
        for name in batch:
            if name not in completed_set:
                return name
    return batch[-1] if batch else ""


def _find_structured_block(stderr: str):
    """Locate the first "N. <path>:<line>" block followed by a separator line."""
    lines = strip_ansi(stderr).splitlines()
    for idx, line in enumerate(lines):
        header = STRUCTURED_HEADER_PATTERN.match(line)
        if header and idx + 1 < len(lines) and SEPARATOR_PATTERN.match(lines[idx + 1].strip()):
            return header.group(1).strip(), int(header.group(2)), lines[idx:]
    return None


def _format_wrong_result(test_path: str, line_number: int, block_lines: list):
    mismatch_desc = ""
    actual = ""
    expected = ""
    for idx, line in enumerate(block_lines):
        stripped = line.strip()
        if MISMATCH_PATTERN.match(stripped):
            mismatch_desc = stripped
            for follow in block_lines[idx + 1:]:
                value_match = VALUE_MISMATCH_PATTERN.match(follow.strip())
                if value_match:
                    actual = value_match.group(1).strip()
                    expected = value_match.group(2).strip()
                    break
            break
    summary = f"expected: {expected}, got {actual}; {mismatch_desc}"
    lines = [f"error: FAIL {test_path}", "", summary, ""]
    try:
        lines.extend(render_test_snippet(test_path, line_number))
    except OSError:
        pass
    return lines


def _format_generic_structured(test_path: str, block_lines: list):
    content = []
    for line in block_lines:
        if line.lstrip().startswith(CATCH_TRAILER_PREFIX):
            break
        content.append(line)
    while content and content[-1].strip() == "":
        content.pop()
    return [f"error: FAIL {test_path}", "", *content]


def _detect_fatal_signal(stdout: str):
    lines = strip_ansi(stdout).splitlines()
    if not any("FAILED:" in line for line in lines):
        return None
    if not any("fatal error condition" in line for line in lines):
        return None
    for line in lines:
        signal_match = SIGNAL_PATTERN.match(line.strip())
        if signal_match:
            return signal_match.group(1).strip()
    return None


def _detect_explicit_failure(stdout: str):
    lines = strip_ansi(stdout).splitlines()
    for idx, line in enumerate(lines):
        if line.strip().startswith(EXPLICIT_MESSAGE_MARKER):
            test_path = ""
            for back in range(idx - 1, -1, -1):
                source_match = FAILED_SOURCE_PATTERN.match(lines[back].strip())
                if source_match:
                    test_path = source_match.group(1).strip()
                    break
            message_text = ""
            for follow in lines[idx + 1:]:
                if follow.strip():
                    message_text = follow.strip()
                    break
            return test_path, message_text
    return None


def _format_fallback(message: str | None, stdout: str, stderr: str, batch: list):
    test_path = batch[0] if batch else ""
    header = message.strip() if message else f"error: FAIL {test_path}"
    lines = [header]
    body = []
    if stdout.strip():
        body.extend(strip_ansi(stdout).strip().splitlines())
    if stderr.strip():
        body.extend(strip_ansi(stderr).strip().splitlines())
    if body:
        lines.append("")
        lines.extend(body)
    return lines, list(batch)


def render_test_snippet(test_name: str, line_number: int) -> list[str]:
    with open(test_name, "r", encoding="utf8", errors="backslashreplace") as f:
        file_lines = f.read().split("\n")
    total = len(file_lines)
    target_idx = line_number - 1
    if target_idx < 0 or target_idx >= total:
        return []

    # Expand backward to the nearest preceding blank line and forward to the
    # nearest following blank line; the blank boundaries get trimmed below.
    start = 0
    for idx in range(target_idx - 1, -1, -1):
        if file_lines[idx].strip() == "":
            start = idx
            break
    end = total - 1
    for idx in range(target_idx + 1, total):
        if file_lines[idx].strip() == "":
            end = idx
            break

    window = [(idx + 1, file_lines[idx]) for idx in range(start, end + 1)]
    while window and window[0][1].strip() == "":
        window.pop(0)
    while window and window[-1][1].strip() == "":
        window.pop()
    if not window:
        return []

    width = len(str(max(number for number, _ in window)))
    rendered = []
    for number, content in window:
        padded = str(number).rjust(width)
        if number == line_number:
            rendered.append(f"  > {padded}  {content}")
        else:
            rendered.append(f"    {padded}  {content}")
    return rendered


